import React from 'react';
import { Link } from 'react-router-dom';

const styles = {
  footer: {
    backgroundColor: '#1a202c', // Dark blue background from the image
    color: '#a0aec0', // Default light gray text color
    padding: '50px 30px',
    fontFamily: 'sans-serif',
  },
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
  },
  // Main content area with branding and nav
  mainContent: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    flexWrap: 'wrap', // Allows columns to stack on small screens
    gap: '30px', // Adds space between columns when they stack
    paddingBottom: '30px',
    marginBottom: '30px',
    borderBottom: '1px solid #2d3748', // The subtle horizontal line
  },
  // Left column for branding
  branding: {
    textAlign: 'left',
  },
  clinicName: {
    color: '#ffffff', // Bright white for the name
    fontSize: '2rem',
    fontWeight: 'bold',
    margin: '0 0 8px 0',
  },
  tagline: {
    color: '#a0aec0', // Softer color for the tagline
    fontSize: '1rem',
    margin: 0,
    fontStyle: 'italic',
  },
  // Right column for navigation
  nav: {
    display: 'flex',
    gap: '25px', // Space between menu items
    flexWrap: 'wrap', // Allows links to wrap if space is tight
  },
  copyright: {
    textAlign: 'center',
    fontSize: '0.9rem',
    color: '#a0aec0',
  }
};

// CSS for link hover effects (more performant than JS state)
const dynamicStyles = `
  .footer-nav-link {
    color: #a0aec0; /* Default link color */
    text-decoration: none;
    font-size: 1rem;
    transition: color 0.3s ease;
  }

  .footer-nav-link:hover {
    color: #ffffff; /* Brighter white on hover */
  }
`;

const Footer = () => {
  // Array of footer links for easy management
  const footerLinks = [
    { text: 'Home', path: '/', isRouterLink: true },
    { text: 'About Us', path: '/about', isRouterLink: true },
    { text: 'Services', path: '/#services', isRouterLink: false },
    { text: 'Contact Us', path: '/#contact', isRouterLink: false },
    { text: 'Terms and Conditions', path: '/terms', isRouterLink: true },
  ];

  return (
    <>
      {/* This injects the link hover styles into the document */}
      <style>{dynamicStyles}</style>

      <footer style={styles.footer}>
        <div style={styles.container}>
          <div style={styles.mainContent}>
            {/* Left Column: Branding */}
            <div style={styles.branding}>
              <h2 style={styles.clinicName}>Karpagam Clinic</h2>
              <p style={styles.tagline}>Your Health, Our Priority</p>
            </div>

            {/* Right Column: Navigation */}
            <nav style={styles.nav}>
              {footerLinks.map(({ text, path, isRouterLink }) => 
                isRouterLink ? (
                  <Link key={text} to={path} className="footer-nav-link">
                    {text}
                  </Link>
                ) : (
                  <a key={text} href={path} className="footer-nav-link">
                    {text}
                  </a>
                )
              )}
            </nav>
          </div>

          {/* Copyright Section */}
          <p style={styles.copyright}>
            © {new Date().getFullYear()} Karpagam Clinic. All Rights Reserved.
          </p>
        </div>
      </footer>
    </>
  );
};

export default Footer;
